#!/usr/bin/env node
import { mkdtempSync,mkdirSync,readFileSync,readdirSync,rmSync,statSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),".."),tmp=mkdtempSync(path.join(tmpdir(),"agent-plugins-offline-")),archive=path.join(tmp,"agent-plugins.zip"),extracted=path.join(tmp,"extracted"),key=process.platform+"-"+process.arch,ext=process.platform==="win32"?".exe":"";
const clean={PATH:"",HOME:tmp,NODE_PATH:"",BUN_INSTALL:"",npm_config_offline:"true",LANG:"C",LC_ALL:"C"};
try{let result=spawnSync(process.execPath,[path.join(root,"scripts","package-offline.mjs"),archive],{cwd:root,encoding:"utf8",timeout:180000});if(result.status!==0)throw new Error(result.stderr||result.stdout);mkdirSync(extracted);result=spawnSync("unzip",["-q",archive,"-d",extracted],{encoding:"utf8"});if(result.status!==0)throw new Error(result.stderr);const plugin=path.join(extracted,"agent-plugins"),files=[];function walk(dir){for(const name of readdirSync(dir)){const full=path.join(dir,name);if(statSync(full).isDirectory())walk(full);else files.push(path.relative(plugin,full).split(path.sep).join("/"));}}walk(plugin);for(const forbidden of ["apps/","tests/","vendor/","node_modules/","package.json"])if(files.some(f=>f===forbidden.slice(0,-1)||f.startsWith(forbidden)))throw new Error("runtime archive contains source-only material: "+forbidden);if(!files.includes("release-manifest.json"))throw new Error("missing staging manifest");for(const name of ["skill-creator","agent-creator","hook-creator","plugin-creator"]){const bin=path.join(plugin,"skills",name,"scripts",name+ext);const smoke=spawnSync(bin,["--help"],{cwd:tmp,env:clean,encoding:"utf8",timeout:30000});if(smoke.status!==0)throw new Error(name+": "+(smoke.stderr||smoke.stdout));}const manifest=JSON.parse(readFileSync(path.join(plugin,"release-manifest.json"),"utf8"));if(manifest.releaseKey!==key)throw new Error("wrong release target");console.log(JSON.stringify({status:"passed",releaseKey:key,files:files.length}));}finally{if(!process.env.KEEP_OFFLINE_TEST)rmSync(tmp,{recursive:true,force:true});}
